#!/usr/bin/env bash
#
# Rewrites block-scoped C# namespaces (`namespace X { ... }`) as file-scoped ones (`namespace X;`)
# and removes the indentation level the block added. The code base uses file-scoped namespaces
# only, but `dotnet ef migrations add` writes block-scoped ones, and `dotnet format` skips the
# Designer and snapshot files it writes because they carry `// <auto-generated />`. Run it after
# every `dotnet ef migrations add` (see AGENTS.md, Storage).
#
# Arguments: one or more .cs files or directories (searched recursively for *.cs).
#
#   src/script/development/file-scoped-namespaces.sh src/dotnet/src/Ninlil.Dns.Data.EntityFrameworkCore.Migrations.*/Migrations
#
# Rewrites each file in place and prints the files it changed. A file that has no block-scoped
# namespace is left untouched, so re-running it is safe. Every line inside the block loses up to
# four leading spaces; a raw string literal ("""...""") keeps its value because its closing
# delimiter moves left by the same amount. Exits non-zero when an argument does not exist or a
# file opens a namespace block that never closes.

set -euo pipefail

if [[ $# -eq 0 ]]; then
    echo "Usage: $0 <file.cs | directory>..." >&2
    exit 1
fi

convert() {
    local file="$1"
    local converted
    # The namespace line must be followed by a line holding only "{", and the block ends at the
    # last line holding only "}" in column zero. Trailing carriage returns are kept as they are.
    converted="$(awk '
        { lines[NR] = $0 }
        END {
            ns = 0
            for (i = 1; i < NR; i++) {
                if (lines[i] ~ /^namespace [A-Za-z0-9_.]+[[:space:]]*$/ && lines[i + 1] ~ /^\{\r?$/) { ns = i; break }
            }
            if (ns == 0) { exit 3 }
            close_line = 0
            for (i = NR; i > ns + 1; i--) {
                if (lines[i] ~ /^\}\r?$/) { close_line = i; break }
            }
            if (close_line == 0) { exit 4 }
            cr = (lines[ns] ~ /\r$/) ? "\r" : ""
            name = lines[ns]
            sub(/[[:space:]]*$/, "", name)
            for (i = 1; i < ns; i++) print lines[i]
            print name ";" cr
            if (lines[ns + 2] !~ /^\r?$/) print cr
            for (i = ns + 2; i < close_line; i++) {
                line = lines[i]
                sub(/^( {1,4})/, "", line)
                print line
            }
            for (i = close_line + 1; i <= NR; i++) print lines[i]
        }
    ' "$file")" || {
        local status=$?
        if [[ $status -eq 3 ]]; then
            return 0
        fi
        echo "$file: the namespace block has no closing brace in column zero" >&2
        return 1
    }
    # Command substitution drops the trailing newline; the C# files end with one.
    printf '%s\n' "$converted" >"$file"
    echo "$file"
}

status=0
for target in "$@"; do
    if [[ -d "$target" ]]; then
        while IFS= read -r -d '' file; do
            convert "$file" || status=1
        done < <(find "$target" -name '*.cs' -not -path '*/obj/*' -not -path '*/bin/*' -print0)
    elif [[ -f "$target" ]]; then
        convert "$target" || status=1
    else
        echo "$target: no such file or directory" >&2
        status=1
    fi
done
exit $status
